	gid := goroutineID()
	gate.mu.Lock()
	if gate.owner == gid {
		gate.depth++
		gate.mu.Unlock()
		return gate, false, func() {
			gate.mu.Lock()
			gate.depth--
			gate.mu.Unlock()
