	// consistent order and cannot deadlock against each other.
	slices.SortFunc(locks, func(a, b stateLock) int { return strings.Compare(a.path, b.path) })

	releases := make([]func(), 0, len(locks))
	releaseAll := func() {
		for i := len(releases) - 1; i >= 0; i-- {
			releases[i]()
		}
