	warnFile := session.SessionStateDirName + "/" + staleEndedSessionWarnFile
	if info, statErr := root.Lstat(warnFile); statErr == nil {
		if time.Since(info.ModTime()) < staleEndedSessionWarnInterval {
			return // rate-limited
