// capturedSyncRemotesFileName is the per-clone captured-election state, stored
// in the git common dir (worktree-shared, like the push queue). List-shaped
// from day one: phase 1 caps membership at one remote, and lifting the cap
// (per-remote push-queue tracking) must not need a state migration.
const capturedSyncRemotesFileName = "entire-checkpoint-sync-remotes.json"

// capturedSyncRemotesLockName serializes the read-decide-write in
// commitCapturedSyncRemote. Paired with the state file exactly as
// checkpoint/pushqueue.go pairs its queue and lock in this same directory: the
// atomic write below keeps readers safe, but without the lock two concurrent
// pre-push hooks in different worktrees both observe "nothing captured", both
// write, and last-rename-wins — so each announces a different remote and "first
// capture sticks" becomes a coin flip.
const capturedSyncRemotesLockName = "entire-checkpoint-sync-remotes.lock"

type capturedSyncRemotesFile struct {
	Remotes []string `json:"remotes"`
}

// capturedSyncRemotesRoot returns the shared *os.Root over the git common dir,
// where both the captured election and its lock live. Both are fixed names, so
// the root buys uniformity here rather than protection from a crafted name —
// which is the point: one way to reach .git means no call site to audit.
func capturedSyncRemotesRoot(ctx context.Context) (*os.Root, error) {
	return gitdir.Open(ctx) //nolint:wrapcheck // gitdir already names the directory and the failure
}

// loadCapturedSyncRemotes reads the captured election. Fail-soft: a missing,
// unreadable, or corrupt file reads as "nothing captured" — capture is
// automatic state, so unlike the explicit checkpoint_push_remote setting it
// must never fail sync closed.
func loadCapturedSyncRemotes(ctx context.Context) []string {
	root, err := capturedSyncRemotesRoot(ctx)
	if err != nil {
		return nil
	}
	data, err := osroot.ReadFileNoFollow(root, capturedSyncRemotesFileName)
	if err != nil {
		return nil
	}
	var f capturedSyncRemotesFile
	if err := json.Unmarshal(data, &f); err != nil {
		logging.Debug(ctx, "captured sync remotes file unreadable; ignoring",
			slog.String("error", err.Error()))
		return nil
	}
	return f.Remotes
}

// saveCapturedSyncRemote persists the one captured remote. Singular on purpose:
// phase 1 caps membership at one, and a plural writer left that cap resting on a
// single call site passing a one-element literal. The on-disk shape stays
// list-shaped, so lifting the cap in phase 2 needs a new writer rather than a
// migration.
func saveCapturedSyncRemote(ctx context.Context, name string) error {
	root, err := capturedSyncRemotesRoot(ctx)
	if err != nil {
		return err
	}
	data, err := json.Marshal(capturedSyncRemotesFile{Remotes: []string{name}})
	if err != nil {
		return fmt.Errorf("encode captured sync remotes: %w", err)
	}
	if err := jsonutil.WriteFileAtomicIn(root, capturedSyncRemotesFileName, data, 0o600); err != nil {
		return fmt.Errorf("write captured sync remotes: %w", err)
	}
	return nil
}

// pendingCaptureCheckpointSyncRemote reports the remote this push would e…2961 tokens truncated…nfunc hasUserContent(message string) bool {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	for _, line := range strings.Split(message, "\n") {
		trimmed := strings.TrimSpace(line)
		// Skip empty lines
		if trimmed == "" {
			continue
		}
		// Skip comment lines
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		// Skip our trailer line
		if strings.HasPrefix(trimmed, trailerPrefix) {
			continue
		}
		// Found user content
		return true
	}
	return false
}

// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
func stripCheckpointTrailer(message string) string {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	var result []string
	for _, line := range strings.Split(message, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
			result = append(result, line)
		}
	}
	return strings.Join(result, "\n")
}

// isGitSequenceOperation checks if git is currently in the middle of a rebase,
// cherry-pick, or revert operation. During these operations, commits are being
// replayed and should not be linked to agent sessions.
//
// Detects:
//   - rebase: .git/rebase-merge/ or .git/rebase-apply/ directories
//   - cherry-pick: .git/CHERRY_PICK_HEAD file
//   - revert: .git/REVERT_HEAD file
func isGitSequenceOperation(ctx context.Context) bool {
	// Get git directory (handles worktrees and relative paths correctly)
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// These markers live in the PER-WORKTREE git dir, not the common dir, which
	// is why this opens gitDir rather than using gitdir.Open.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// Check for rebase state directories, then cherry-pick and revert state files.
	for _, marker := range []string{"rebase-merge", "rebase-apply", "CHERRY_PICK_HEAD", "REVERT_HEAD"} {
		if _, err := root.Lstat(marker); err == nil {
			return true
		}
	}

	return false
}

