	require.NoError(t, err)
	require.Equal(t, filepath.Join(target, ".git"), gitDir)
	common, err := gitCommonDirForWorktree(ctx, target)
	require.NoError(t, err)
	physical, err := filepath.EvalSymlinks(filepath.Join(target, ".git"))
	require.NoError(t, err)
